package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b int64
	fmt.Fscan(in, &a, &b)

	count := func(x int64) int64 {
		if x <= 0 {
			return 0
		}
		var res int64 = 0
		// numbers with exactly one zero in binary, no leading zeros
		// form: all bits 1 except exactly one 0 inside
		// length L >= 2, choose position of zero (not leading)
		for L := 2; ; L++ {
			// smallest number of length L with one zero is when zero at position 0 (LSB)
			// value = 2^L - 2
			minVal := (int64(1) << L) - 2
			if minVal > x {
				break
			}
			for z := 0; z <= L-2; z++ {
				// value = (2^L - 1) - 2^z
				val := (int64(1) << L) - 1 - (int64(1) << z)
				if val > x {
					continue
				}
				res++
			}
		}
		return res
	}

	ans := count(b) - count(a-1)
	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, ans)
	out.Flush()
}

