import (
	"bufio"
	"fmt"
	"os"
)

func countUpTo(x int64) int64 {
	if x <= 0 {
		return 0
	}
	var res int64 = 0
	// For each bit length L
	for L := 2; ; L++ {
		// highest bit index is L-1, must be 1
		// zero position i from 0 to L-2
		// number = (1<<(L-1)) + sum_{j!=i, j<L-1} (1<<j)
		//       = (1<<L) - 1 - (1<<i)
		n := int64(1<<L) - 1
		if n > x+1 { // minimal when i=L-2: n - (1<<(L-2)) ~ (1<<L) - 1 - (1<<(L-2))
			// but for safety, break when smallest possible exceeds x
			if int64(1<<(L-1)) > x { // smallest with this L is when zero at position 0: (1<<L)-1-1
				break
			}
		}
		for i := 0; i < L-1; i++ {
			val := int64((1<<L) - 1 - (1 << i))
			if val > x {
				continue
			}
			res++
		}
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b int64
	fmt.Fscan(in, &a, &b)
	ans := countUpTo(b) - countUpTo(a-1)
	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, ans)
	out.Flush()
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func count(n int64) int64 {
	if n <= 0 {
		return 0
	}
	var res int64 = 0
	// For each bit length L (number of bits)
	for L := 2; ; L++ {
		// Highest number with L bits: all ones
		maxVal := (int64(1) << uint(L)) - 1
		if maxVal > n {
			break
		}
		// Position of zero bit (0-based from LSB)
		for z := 0; z < L; z++ {
			// Skip leading zero (MSB cannot be zero)
			if z == L-1 {
				continue
			}
			// Build number: all ones except bit z is zero
			val := maxVal & ^(int64(1) << uint(z))
			if val <= n {
				res++
			}
		}
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b int64
	fmt.Fscan(in, &a, &b)
	ans := count(b) - count(a-1)
	fmt.Println(ans)
}

