	in := bufio.NewReader(os.Stdin)
	var a, b int64
	fmt.Fscan(in, &a, &b)

	count := int64(0)

	// For each possible length of binary representation
	for k := 2; ; k++ {
		// minimal and maximal numbers with k bits
		minVal := int64(1) << (k - 1)
		if minVal > b {
			break
		}
		maxVal := (int64(1) << k) - 1

		// For each position of the single zero (not at leading bit)
		for i := 0; i < k-1; i++ {
			// zero at position i (0 = LSB)
			val := maxVal - (int64(1) << i)
			if val < a || val > b {
				continue
			}
			// ensure no leading zero (MSB must be 1) – already guaranteed by construction
			count++
		}
	}

	fmt.Println(count)
}

