	var a, b uint64
	fmt.Fscan(in, &a, &b)

	count := func(x uint64) uint64 {
		if x == 0 {
			return 0
		}
		var res uint64 = 0
		// For each length of binary representation
		for k := 2; ; k++ {
			// smallest number with k bits and exactly one zero:
			// zero at position 0 (LSB): (1<<(k-1)) + (1<<1) + ... + (1<<(k-1))? easier: all ones except one zero
			// But we'll generate directly and break when min > x
			// min for given k is when zero at position 0: ( (1<<k) - 1 ) - 1
			minVal := (uint64(1) << k) - 2
			if minVal > x {
				break
			}
			// zero position from 0 to k-1 (0 is LSB)
			for z := 0; z < k; z++ {
				// all ones of length k
				val := (uint64(1) << k) - 1
				// clear bit at position z
				val &^= (uint64(1) << z)
				if val > x {
					continue
				}
				res++
			}
		}
		return res
	}

	ans := count(b) - count(a-1)
	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, ans)
	out.Flush()
}
