package main

import (
	"bufio"
	"fmt"
	"os"
)

func count(n int64) int64 {
	if n <= 0 {
		return 0
	}
	var res int64 = 0
	// lengths from 2 to 60 (since 2^60 > 1e18)
	for L := 2; L <= 60; L++ {
		for z := 1; z < L-1; z++ {
			x := (int64(1) << L) - 1 - (int64(1) << z)
			if x > n {
				continue
			}
			res++
		}
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b int64
	fmt.Fscan(in, &a, &b)
	ans := count(b) - count(a-1)
	fmt.Println(ans)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b int64
	if _, err := fmt.Fscan(in, &a, &b); err != nil {
		return
	}

	count := func(x int64) int64 {
		if x <= 0 {
			return 0
		}
		var res int64 = 0
		// length of binary representation (number of bits)
		for L := 2; ; L++ {
			// smallest number with L bits is 1<<(L-1)
			if (int64(1) << (L - 1)) > x {
				break
			}
			// positions of zero bit: from 0 to L-2 (0 is LSB)
			for z := 0; z <= L-2; z++ {
				// construct number: all bits 1 except bit z is 0, and highest bit (L-1) is 1
				n := (int64(1) << L) - 1 - (int64(1) << z)
				if n <= x {
					res++
				}
			}
		}
		return res
	}

	ans := count(b) - count(a-1)
	writer := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(writer, ans)
	writer.Flush()
}
